/// <summary>
/// Logs a successful ABN validation web service call.
/// </summary>
internal final class METTelemetryABNValidationEvent extends ISMTelemetryBase
{
    private METABNValidationJobQueue abnValidationJobQueue;
    private int64                    durationMilliseconds;

}

Method.Source:
/// <summary>
/// Initializes the class <c>METTelemetryABNValidationEvent</c>.
/// </summary>
/// <returns>Instance of <c>METTelemetryABNValidationEvent</c>.</returns>
public static METTelemetryABNValidationEvent construct()
{
    return new METTelemetryABNValidationEvent();
}

/// <summary>
/// Runs the ABN validation success event.
/// </summary>
/// <param name = "_queue">Queue record being processed.</param>
/// <param name = "_durationMilliseconds">Elapsed time of the web service call.</param>
public static void runTelemetryEvent(METABNValidationJobQueue _queue, int64 _durationMilliseconds)
{
    METTelemetryABNValidationEvent abnValidationEvent = METTelemetryABNValidationEvent::construct();

    abnValidationEvent.initFromQueue(_queue, _durationMilliseconds);
    abnValidationEvent.addRunTimePropertyToAppinsights();
    abnValidationEvent.processEvent(METTelemetryEventNames::ABNValidationEvent);
}

/// <summary>
/// Initializes the parameter setup values.
/// </summary>
/// <param name = "_parameterSetup">The parameter setup record to initialize.</param>
protected void initializeParameterSetup(ISMTelemetryParameterSetup _parameterSetup)
{
    _parameterSetup.TelemetryClass = this.telemetryName();
    _parameterSetup.IsEnabled      = NoYes::Yes;
    _parameterSetup.SeverityLevel  = ISMTelemetrySeverityLevel::Information;
}

/// <summary>
/// Determines whether the event should be logged.
/// </summary>
/// <returns>Always true; enablement is controlled by the parameter setup.</returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// No post population required.
/// </summary>
protected void postPopulateProperties()
{
}

/// <summary>
/// Stores the queue buffer that provides the telemetry context.
/// </summary>
/// <param name = "_queue">Queue record being processed.</param>
/// <param name = "_durationMilliseconds">Elapsed time of the web service call.</param>
private void initFromQueue(METABNValidationJobQueue _queue, int64 _durationMilliseconds)
{
    abnValidationJobQueue = _queue;
    durationMilliseconds  = _durationMilliseconds;
}

/// <summary>
/// Adds runtime telemetry properties to application insights.
/// </summary>
public void addRunTimePropertyToAppinsights()
{
    this.addRuntimeProperty('customerNumber',       abnValidationJobQueue.CustAccount);
    this.addRuntimeProperty('abnNumber',            abnValidationJobQueue.ABN);
    this.addRuntimeProperty('outcome',              METABNValidationOutcomes::Success);
    this.addRuntimeProperty('failureType',          METABNValidationFailureTypes::None);
    this.addRuntimeProperty('referenceTable',       abnValidationJobQueue.RefTableId ? tableId2Name(abnValidationJobQueue.RefTableId) : '');
    this.addRuntimeProperty('referenceRecId',       int642Str(abnValidationJobQueue.RefRecId));
    this.addRuntimeProperty('processId',            guid2Str(abnValidationJobQueue.ProcessId));
    this.addRuntimeProperty('durationMilliseconds', int642Str(durationMilliseconds));
    this.addRuntimeProperty('legalEntity',          curExt());
}
